const assert=require("node:assert/strict");
const keys=JSON.parse(process.env.INTERNAL_EVENT_API_PROJECT_KEYS_JSON||"{}");
assert(keys["server-core"]&&keys["server-core"].length>=32);
assert(process.env.INTERNAL_EVENT_API_TOKEN);
const body=JSON.stringify({eventId:"gace-key-probe-"+Date.now(),eventType:"gace.internal.key.probe",sourceId:"server-core",destinationId:"gace-probe-unknown-destination",data:{probe:true}});
(async()=>{
const result={};
for(const [name,k] of Object.entries({missing:"",wrong:"invalid-key-negative-case",legacy:process.env.INTERNAL_EVENT_API_TOKEN,project:keys["server-core"]})){
const headers={"content-type":"application/json"};if(k)headers["x-internal-api-token"]=k;
const r=await fetch("http://127.0.0.1:7373/internal/events",{method:"POST",headers,body});result[name]=r.status;
}
const h=await fetch("http://127.0.0.1:7373/healthz");
console.log(JSON.stringify({health:h.status,auth_status:result,key_values_logged:false}));
if(h.status!==200||result.missing!==401||result.wrong!==401||result.legacy!==422||result.project!==422)process.exit(2);
})().catch(()=>process.exit(3));
